insert into public.interactive_assignment_templates(slug,day,title,target_slugs,is_lab) values ('day-16-foundation-net-force-from-diagrams',16,'Day 16 · Foundation: Net force from diagrams',array['u1.net-force-from-fbd'],false);
insert into public.daily_lesson_templates(key,foundation_slug,review_slug,foundation_questions,review_questions,quiz) values ('unit-1-day-16','day-16-foundation-net-force-from-diagrams','day-16-net-force',array['f16-floor','f16-arrows','f16-slope','f16-thrust','f16-exit'],array['r2-1a','r2-1b','r2-1c','r2-2a','r2-2b','r2-2c','r2-3a','r2-3b','r2-3c','r2-4a','r2-4b','r2-4c','r2-5a','r2-5b'],'{"title":"Day 16 · Quiz: Net force from diagrams","instructions":"Choose an axis. Keep direction and units in each answer.","questions":[{"kind":"choice","points":1,"prompt":"A 4 kg box feels 18 N right and 6 N left. What is its acceleration?","options":["3 m/s² right","6 m/s² right","12 m/s² right","3 m/s² left"],"correct_index":0,"guide":"The net force is 12 N right. Divide by 4 kg.","demand":{"blooms":"Apply","dok":2,"evidence":"Uses a signed sum and the object’s mass."}},{"kind":"choice","points":1,"prompt":"Which direction does the normal force on a block point on a tilted ramp?","options":["Vertically up","Perpendicular to and away from the ramp","Down the ramp","Into the ramp"],"correct_index":1,"guide":"The normal force is perpendicular to the contact surface.","demand":{"blooms":"Understand","dok":1,"evidence":"Distinguishes support from weight."}},{"kind":"written","points":3,"prompt":"A 3 kg block slides down a ramp. Weight contributes 12 N downhill and friction is 3 N uphill. Find the along-ramp net force and acceleration. Explain why the full weight is not added again.","guide":"Taking downhill as positive gives 9 N downhill and 3 m/s² downhill. The 12 N already describes the along-ramp contribution of weight.","demand":{"blooms":"Analyze","dok":2,"evidence":"Uses components once in a signed sum."}},{"kind":"written","points":3,"prompt":"A cart moves left while a net force points right. What happens to its speed at first? Explain using the directions of velocity and acceleration.","guide":"The acceleration points right with the net force. While velocity points left, the cart slows down.","demand":{"blooms":"Analyze","dok":2,"evidence":"Distinguishes motion from acceleration."}}]}'::jsonb);
